export const GetReconstructionReferenceResponse = zod.unknown()

/**
 * One trace per square ROI of a complete point, in the request's order, against the depth (µm) and the depth
 * index, as lauelab's `plot_roi_traces` plots them: the sum of the ROI's stored pixels at each depth, or with
 * `normalize` that divided by its own maximum (a trace whose maximum is not positive has no values, and the
 * reason). Each square is centred as near as it can be to `x`, `y`: never clipped or
 * shifted, so one that would extend outside the image is a 422 naming it (`["rois", i]`), and nothing is read. At
 * most 32 ROIs. Each ROI's trace is kept: those not computed yet are computed together, in one pass over the
 * point's frames, which waits for a turn, as the trace. Reads only. Otherwise the frames' errors.
 *
 * Needs the header `X-Laue-Portal: 1`, as every request that changes data (the portal's pages send it; scripts must too). Without it, or from a page on another origin (a `Sec-Fetch-Site` other than `same-origin` or `none`), the answer is a 403 problem and nothing changes.
 * @summary Compute a point's ROI traces
 */
export const computeReconstructionRoiTracesPathReconstructionIdMin = 0;
export const computeReconstructionRoiTracesPathReconstructionIdMax = 9223372036854776000;



export const ComputeReconstructionRoiTracesParams = zod.object({
  "reconstruction_id": zod.int().min(computeReconstructionRoiTracesPathReconstructionIdMin).max(computeReconstructionRoiTracesPathReconstructionIdMax).describe('The reconstruction run\'s ID (`R<id>`).'),
  "point_id": zod.string().describe('The point\'s ID (`point_id` of the points: lauelab\'s; per-depth files: the summary\'s prefix).')
})

export const computeReconstructionRoiTracesBodyNormalizeDefault = false;
export const computeReconstructionRoiTracesBodyRoisItemSizeMax = 65535;

export const computeReconstructionRoiTracesBodyRoisMax = 32;



export const ComputeReconstructionRoiTracesBody = zod.object({
  "normalize": zod.boolean().default(computeReconstructionRoiTracesBodyNormalizeDefault).describe('Divide each trace by its own maximum (lauelab\'s ``plot_roi_traces(normalized=True)``).'),
  "rois": zod.array(zod.object({
  "size": zod.int().min(1).max(computeReconstructionRoiTracesBodyRoisItemSizeMax).describe('The square\'s side in pixels.'),
  "x": zod.number().describe('The position in stored-image pixels, zero-based (a whole number is a pixel\'s centre): across.'),
  "y": zod.number().describe('Down.')
}).describe('A square ROI as the page places it: its side, centred as near as it can be to a position.')).max(computeReconstructionRoiTracesBodyRoisMax).describe('The ROIs, in the order of the answer\'s traces; each must lie inside the image (none is clipped or\nshifted).')
}).describe('The ROIs to trace through a point\'s depths.')

export const computeReconstructionRoiTracesResponseTracesItemBoundsMin = 4;
export const computeReconstructionRoiTracesResponseTracesItemBoundsMax = 4;



export const ComputeReconstructionRoiTracesResponse = zod.object({
  "depth_index": zod.array(zod.int()).describe('The depth indices (``0`` to ``n - 1``), the other axis.'),
  "depth_um": zod.array(zod.number()).describe('Each depth frame\'s depth (µm), by depth index.'),
  "normalize": zod.boolean(),
  "point_id": zod.string(),
  "reconstruction_id": zod.int(),
  "traces": zod.array(zod.object({
  "bounds": zod.array(zod.int()).min(computeReconstructionRoiTracesResponseTracesItemBoundsMin).max(computeReconstructionRoiTracesResponseTracesItemBoundsMax).describe('The pixels it sums, ``[y0, y1, x0, x1]`` (half-open: rows ``y0`` to ``y1 - 1``).'),
  "reason": zod.union([zod.string(),zod.null()]).describe('Why a trace cannot be normalized (its maximum is not positive), as lauelab says it; null otherwise.'),
  "values": zod.union([zod.array(zod.union([zod.number(),zod.null()])),zod.null()]).describe('The sum of its stored pixels at each depth, or that divided by its maximum with ``normalize`` (null for a\nvalue that is not finite); null when it cannot be normalized (``reason``).')
}).describe('One ROI\'s trace through depth.'))
}).describe('One trace per ROI of a point, in the request\'s order, against the depth (µm) and the depth index.')

/**
 * A complete point's full-frame intensity at every depth, with the depths in µm and its brightest depth (the
 * Depth View opens there): a scan point's stored reduction, or per-depth files summed one frame at a time.
 * Revalidated by its `ETag`, as the frames. One not computed yet waits for a turn (two at a time): 503 with
 * `Retry-After` while four already wait, and a request whose client has gone stops waiting. Otherwise the frames'
 * errors.
 * @summary Get a point's intensity trace
 */
export const getReconstructionTracePathReconstructionIdMin = 0;
export const getReconstructionTracePathReconstructionIdMax = 9223372036854776000;



export const GetReconstructionTraceParams = zod.object({
  "reconstruction_id": zod.int().min(getReconstructionTracePathReconstructionIdMin).max(getReconstructionTracePathReconstructionIdMax).describe('The reconstruction run\'s ID (`R<id>`).'),
  "point_id": zod.string().describe('The point\'s ID (`point_id` of the points: lauelab\'s; per-depth files: the summary\'s prefix).')
})

export const GetReconstructionTraceResponse = zod.object({
  "brightest_index": zod.int().describe('The depth index of the largest value (the first of equal ones): where the Depth View opens the point.'),
  "depth_um": zod.array(zod.number()).describe('Each depth frame\'s depth (µm), by depth index.'),
  "point_id": zod.string(),
  "reconstruction_id": zod.int(),
  "values": zod.array(zod.union([zod.number(),zod.null()])).describe('The sum of each depth frame\'s stored pixels, by depth index (null for a value that is not finite).')
}).describe('A point\'s full-frame intensity through depth (the Depth View\'s trace, lauelab\'s ``depth_trace``).')

